pub fn pop<Q>(&mut self, k: &Q) -> Option<V>
where
    KeyRef<K>: Borrow<Q>,
    Q: Hash + Eq + ?Sized,
{
    match self.map.remove(&k) {
        None => None,
        Some(mut old_node) => {
            unsafe {
                ptr::drop_in_place(old_node.key.as_mut_ptr());
            }
            let node_ptr: *mut LruEntry<K, V> = &mut *old_node;
            self.detach(node_ptr);
            unsafe { Some(old_node.val.assume_init()) }
        }
    }
}

